    pub fn jsonStringify(self: @This(), jw: *std.json.Stringify) !void {
        switch (self) {
            .string => |value| try jw.write(value),
            .auto_code_interpreter_tool_param => |value| try jw.write(value),
            .raw => |value| try jw.write(value),
